MATCH (child:Character)-[:hasFather]->(father:Character {name: 'Hoster Tully'})
MATCH (child)-[:killedBy]->(killer:Character {name: 'Walder Frey'})
RETURN child.name AS character_name;

MATCH (u:FictionalUniverse)
WHERE EXISTS {
    MATCH (u)<-[:fromUniverse]-(c:Character {name: 'Fei Lian'})
} OR EXISTS {
    MATCH (u)<-[:fromUniverse]-(:Character)-[:memberOf]->(:Organization {name: 'Daily Globe'})
}
RETURN count(DISTINCT u) AS numberOfUniverses;

MATCH (u:FictionalUniverse)
WHERE toLower(u.name) CONTAINS toLower('Romance of the Three Kingdoms') 
   OR toLower(u.name) CONTAINS toLower('Three Kingdoms')
   OR toLower(u.name) CONTAINS toLower('Sanguo Yanyi')
MATCH (u)<-[:fromUniverse]-(c:Character)
MATCH (c)-[:diedIn]->(l:Location)
WHERE toLower(l.name) = toLower('Jixian')
RETURN c.name AS name, u.name AS universe
// Note: The Character schema has no birthName property; 
// therefore only the character's name and universe are returned.
// To maximize recall, the universe match includes common aliases for 
// 'Romance of the Three Kingdoms' (e.g., 'Three Kingdoms', 'Sanguo Yanyi').
// Also, the diedIn match is direct on the location name 'Jixian'.
// Verify in the data whether multiple characters (e.g., from the broader 
// Three Kingdoms narrative) have diedIn relationships to a Location named 'Jixian'.
ORDER BY c.name

MATCH (child:Character)-[:hasFather]->(parent:Character {name: "Kevan Lannister"}),
      (child)-[:diedIn]->(deathLocation:Location {name: "Great Sept of Baelor"})
RETURN child.name AS character_name, child.occupation AS occupations;
